<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\SnippetAsset\Application\Usecase\Delete;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\SnippetAssetRef;
use Civi\Lughauth\Features\Document\SnippetAsset\Application\Service\Visibility\SnippetAssetVisibilityService;
use Civi\Lughauth\Features\Document\SnippetAsset\Domain\Gateway\SnippetAssetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetAssetDeleteUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetAssetVisibilityService $visibility,
        private readonly SnippetAssetWriteGateway $writer,
    ) {
    }

    public function allowDelete(?SnippetAssetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of delete usecase for Snippet asset");
        $span = $this->startSpan("Check allow of delete usecase for Snippet asset");
        try {
            $result = $this->dispatcher->dispatch(new SnippetAssetDeleteAllowDecision(Allow::allowed('delete', 'Allowed to delete by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function delete(string $uid): void
    {
        $this->logDebug("Run delete usecase for Snippet asset");
        $span = $this->startSpan("Run delete usecase for Snippet asset");
        try {
            $ref = new SnippetAssetRef($uid);
            $allow = $this->allowDelete($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to delete Snippet asset');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new SnippetAssetDeleteCheck($original));
            $deleted = $original->delete();
            $this->writer->delete($deleted);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
